module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [7:0] in,
    output logic done
);

// State encoding for the FSM
typedef enum logic [1:0] {
    S_IDLE  = 2'b00, // Waiting for the start byte (in[3]=1)
    S1      = 2'b01, // First byte of a message received
    S2      = 2'b10, // Second byte of a message received
    S3      = 2'b11  // Third byte of a message received
} state_type;

state_type state, next_state;
logic next_done;

// State register block (positive edge triggered, synchronous active-high reset)
always @(posedge clk) begin
    if (reset) begin
        state <= S_IDLE;
        done  <= 1'b0;
    end else begin
        state <= next_state;
        done  <= next_done;
    end
end

// Next state and output logic
always @(*) begin
    // Default values to prevent latches
    next_state = S_IDLE;
    next_done  = 1'b0;

    case (state)
        S_IDLE: begin
            // Discard bytes until we see one with in[3]=1
            if (in[3]) begin
                next_state = S1;
            end
            // else remain in S_IDLE
        end

        S1: begin
            // Next incoming byte is assumed to be Byte 2.
            // (in[3] of the other two bytes may be 1 or 0 depending on data)
            next_state = S2;
        end

        S2: begin
            // Next incoming byte is assumed to be Byte 3.
            next_state = S3;
        end

        S3: begin
            // Third byte successfully received.
            // Signal 'done' in the cycle immediately after this one.
            next_state = S_IDLE;
            next_done  = 1'b1;
        end
    endcase
end

endmodule

