module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

// State encoding (Moore machine)
// 3'b000 : S_WL  - walking left on ground
// 3'b001 : S_WR  - walking right on ground
// 3'b010 : S_FL  - falling, will resume left
// 3'b011 : S_FR  - falling, will resume right
// 3'b100 : S_DL  - digging left on ground
// 3'b101 : S_DR  - digging right on ground

reg [2:0] state;

// Next-state logic (registered, updates on positive edge of clk)
// areset is active-high, asynchronous (sampled at posedge clk), resets to S_WL
always @(posedge clk or posedge areset) begin
    if (areset)
        state <= 3'b000;          // reset to walk left
    else
        case (state)
            3'b000: // S_WL - walking left on ground
                if (!ground)      state <= 3'b010;   // fall -> S_FL
                else if (dig)     state <= 3'b100;   // start digging -> S_DL
                else if (bump_left & bump_right) state <= 3'b001; // both bumps -> switch to right
                else if (bump_left) state <= 3'b001; // bump left -> switch to right
                else if (bump_right) state <= 3'b000; // bump right -> stay left
                else               state <= 3'b000; // no change

            3'b001: // S_WR - walking right on ground
                if (!ground)      state <= 3'b011;   // fall -> S_FR
                else if (dig)     state <= 3'b101;   // start digging -> S_DR
                else if (bump_left) state <= 3'b000; // bump left -> switch to left
                else if (bump_right) state <= 3'b001; // bump right -> stay right
                else               state <= 3'b001; // no change

            3'b010: // S_FL - falling (resume left)
                if (ground)       state <= 3'b000; // ground reappears -> resume walking left
                else               state <= 3'b010; // stay falling

            3'b011: // S_FR - falling (resume right)
                if (ground)       state <= 3'b001; // ground reappears -> resume walking right
                else               state <= 3'b011; // stay falling

            3'b100: // S_DL - digging left on ground
                if (!ground)      state <= 3'b010; // ground disappears -> fall (resume left)
                else if (dig)     state <= 3'b100; // continue digging
                else               state <= 3'b000; // dig=0 -> resume walking left

            3'b101: // S_DR - digging right on ground
                if (!ground)      state <= 3'b011; // ground disappears -> fall (resume right)
                else if (dig)     state <= 3'b101; // continue digging
                else               state <= 3'b001; // dig=0 -> resume walking right

            default: state <= 3'b000;           // safety fallback
        endcase
end

// Output logic (Moore: outputs depend only on current state)
assign walk_left = (state == 3'b000);
assign walk_right = (state == 3'b001);
assign aaah       = (state == 3'b010) | (state == 3'b011);
assign digging    = (state == 3'b100) | (state == 3'b101);

endmodule

