        for (i = 0; i < 256; i = i + 1) begin
            // Row and column in the 16×16 grid (rows 0..15, cols 0..15)
            // q[15:0] is row 0, q[31:16] is row 1, …, q[255:240] is row 15.
            // Bit index i maps to row = i/16, col = i%16, with bit 0 = col 0.
            logic [3:0] r = i >> 4;
            logic [3:0] c = i & 15;

            // Toroidal wrap‑around using unsigned 4‑bit overflow/underflow
            logic [3:0] rm1 = r - 1; // 0 wraps to 15
            logic [3:0] rp1 = r + 1; // 15 wraps to 0
            logic [3:0] cm1 = c - 1; // 0 wraps to 15
            logic [3:0] cp1 = c + 1; // 15 wraps to 0

            // Neighbor indices encoded as 8‑bit flat index (row*16 + col)
            logic [7:0] idx_nw = {rm1, cm1};
            logic [7:0] idx_n  = {rm1, c};
            logic [7:0] idx_ne = {rm1, cp1};
            logic [7:0] idx_w  = {r, cm1};
            logic [7:0] idx_e  = {r, cp1};
            logic [7:0] idx_sw = {rp1, cm1};
            logic [7:0] idx_s  = {rp1, c};
            logic [7:0] idx_se = {rp1, cp1};

            // Count live neighbours (max 8, fits in 4 bits)
            logic [3:0] cnt;
            cnt = q[idx_nw] + q[idx_n] + q[idx_ne] +
                  q[idx_w]  + q[idx_e]  +
                  q[idx_sw] + q[idx_s] + q[idx_se];

            // Apply Game of Life rules
            logic next_bit;
            if (cnt <= 1)
                next_bit = 1'b0;            // Rule (1): 0‑1 neighbour → 0
            else if (cnt == 2)
                next_bit = q[i];            // Rule (2): 2 neighbours → stay same
            else if (cnt == 3)
                next_bit = 1'b1;            // Rule (3): 3 neighbours → 1
            else
                next_bit = 1'b0;            // Rule (4): 4+ neighbours → 0

            next_q[i] = next_bit;
        end
    end

endmodule

